// Atelier Morel shop cart: totals, discounts and shipping.
import { round, type Item } from "./price";

export const FREE_SHIPPING_THRESHOLD = 80;
const SHIPPING_FEE = 6.9;

export type Line = { item: Item; quantity: number };

export function subtotal(lines: Line[]): number {
  return lines.reduce((s, l) => s + l.item.price * l.quantity, 0);
}

// “Spring” discount: 10% from three ceramic pieces.
export function discount(lines: Line[]): number {
  const pieces = lines.filter((l) => l.item.category === "ceramics");
  const n = pieces.reduce((s, l) => s + l.quantity, 0);
  return n >= 3 ? subtotal(pieces) * 0.1 : 0;
}

export function shippingFee(total: number): number {
  return total >= FREE_SHIPPING_THRESHOLD ? 0 : SHIPPING_FEE;
}

export function total(lines: Line[]) {
  const st = subtotal(lines);
  const r = discount(lines);
  const shipping = shippingFee(st - r);
  return {
    subtotal: round(st),
    discount: round(r),
    shipping,
    total: round(st - r + shipping),
  };
}

export function addItem(lines: Line[], item: Item): Line[] {
  const i = lines.findIndex((l) => l.item.id === item.id);
  if (i === -1) return [...lines, { item, quantity: 1 }];
  return lines.map((l, j) => (j === i ? { ...l, quantity: l.quantity + 1 } : l));
}

export function removeItem(lines: Line[], id: string): Line[] {
  return lines.filter((l) => l.item.id !== id);
}
